    seed = 1,
    width = M.WIDTH,
    height = M.HEIGHT,
    starting_points = { M.SPAWN },
    no_enemies_mode = true,
    peaceful_mode = true,
    default_enable_all_autoplace_controls = false,
    autoplace_controls = {},
    autoplace_settings = {
      tile = { treat_missing_as_default = false, settings = { ["grass-1"] = { frequency = 1, size = 1, richness = 1 } } },
      entity = { treat_missing_as_default = false, settings = {} },
      decorative = { treat_missing_as_default = false, settings = {} },
    },
    cliff_settings = { name = "cliff", cliff_elevation_0 = 1024, cliff_elevation_interval = 10, richness = 0 },
  }
end

local function circle(cx, cy, r, fn)
  for x = math.floor(cx - r), math.ceil(cx + r) do
    for y = math.floor(cy - r), math.ceil(cy + r) do
      local d = math.sqrt((x + 0.5 - cx) ^ 2 + (y + 0.5 - cy) ^ 2)
      if d <= r then fn(x, y, d) end
    end
  end
end

-- Called once per lake whose area is taken by something the player built (extended map).
local on_lake_blocked = nil
---@param fn fun(surface: LuaSurface, position: MapPosition)
function M.on_lake_blocked(fn) on_lake_blocked = fn end

--- Key of a layout spot in storage.tt_map_blocked: surface, name and position, since several
--- cities share a name (2.6.1). The surface name comes first, up to the first "/".
---@param surface LuaSurface
local function blocked_key(surface, name, x, y)
  return surface.name .. "/" .. name .. "@" .. x .. "," .. y
end
M.blocked_key = blocked_key

--- Place every lake that is missing. On a new map nothing is in the way. On an extended map a
--- lake goes in only if no player entity stands in its area; otherwise it is reported once
--- and retried, like a blocked city.
---@param surface LuaSurface
local function place_lakes(surface)
  storage.tt_map_blocked = storage.tt_map_blocked or {}
  for _, lake in ipairs(M.LAKES) do
    local key = blocked_key(surface, "lake", lake.x, lake.y)
    if surface.get_tile(lake.x, lake.y).name ~= "deepwater" then
      local r = lake.radius + 1
      local area = { { lake.x - r, lake.y - r }, { lake.x + r, lake.y + r } }
      if surface.count_entities_filtered({ area = area, force = "player" }) == 0 then
        local tiles = {}
        circle(lake.x, lake.y, lake.radius, function(x, y, d)
          tiles[#tiles + 1] = { name = d < lake.radius * 0.6 and "deepwater" or "water", position = { x, y } }
        end)
        surface.set_tiles(tiles)
        storage.tt_map_blocked[key] = nil
      elseif not storage.tt_map_blocked[key] then
        storage.tt_map_blocked[key] = true
        if on_lake_blocked then on_lake_blocked(surface, { x = lake.x, y = lake.y }) end
      end
    else
      storage.tt_map_blocked[key] = nil
    end
  end
end

---@param surface LuaSurface
local function place_patches(surface)
  for _, p in ipairs(M.PATCHES) do
    local present = surface.count_entities_filtered({ name = p.name, position = { p.x + 0.5, p.y + 0.5 }, radius = p.radius }) > 0
    if present then
      -- already there
    elseif p.wells then
      for _, w in ipairs(p.wells) do
        surface.create_entity({ name = p.name, position = { p.x + w[1] + 0.5, p.y + w[2] + 0.5 }, amount = p.amount })
      end
    else
      circle(p.x, p.y, p.radius, function(x, y, d)
        local amount = math.floor(p.amount * (1 - 0.5 * d / p.radius))
        surface.create_entity({ name = p.name, position = { x + 0.5, y + 0.5 }, amount = amount })
      end)
    end
  end
end

-- Called once per city whose spot is blocked on an extended map (message to the player).
local on_city_blocked = nil
---@param fn fun(label: string, surface: LuaSurface, position: MapPosition)
function M.on_city_blocked(fn) on_city_blocked = fn end

--- Is any tier of this layout city standing at its spot?
---@param surface LuaSurface
local function city_present(surface, c)
  for _, e in pairs(surface.find_entities_filtered({ position = { c.x + 0.5, c.y + 0.5 }, radius = 1 })) do
    if cities.is_city(e) then return true end
  end
  return false
end

--- Place every layout city that is missing. Never removes anything: a blocked spot is
--- reported once and retried (storage.tt_map_blocked) until it is clear.
---@param surface LuaSurface
local function place_cities(surface)
  storage.tt_map_blocked = storage.tt_map_blocked or {}
  -- keys before 2.6.1 had no position ("surface/name"); place_cities re-records any still blocked
  for key in pairs(storage.tt_map_blocked) do
    if not string.find(key, "@", 1, true) then storage.tt_map_blocked[key] = nil end
  end
  for _, c in ipairs(M.CITIES) do
    if not city_present(surface, c) then
      local pos = { c.x + 0.5, c.y + 0.5 }
      local key = blocked_key(surface, c.name, c.x, c.y)
      if surface.can_place_entity({ name = c.name, position = pos, force = "player" }) then
        cities.place(c.name, surface, pos, "player")
        storage.tt_map_blocked[key] = nil
      elseif not storage.tt_map_blocked[key] then
        storage.tt_map_blocked[key] = true
        if on_city_blocked then on_city_blocked(c.label, surface, { x = pos[1], y = pos[2] }) end
      end
    end
  end
end

--- Put a labelled map tag on every city of the surface. Charting is asynchronous, so tags
--- that can't be placed yet are retried from tick_tags (storage.tt_map_tags_pending).
---@param surface LuaSurface
local function tag_cities(surface)
  storage.tt_map_tags_pending = storage.tt_map_tags_pending or {}
  storage.tt_map_tags_pending[surface.name] = true
end

--- Place pending city map tags (called every GOAL_TICK_INTERVAL). Returns tags placed.
function M.tick_tags()
  local pending = storage.tt_map_tags_pending
  if not pending then return 0 end
  local placed = 0
  for surface_name in pairs(pending) do
    local surface = game.get_surface(surface_name)
    if not surface then
      pending[surface_name] = nil
    else
      local force = game.forces["player"]
      local all = true
      for _, c in ipairs(M.CITIES) do
        local pos = { x = c.x + 0.5, y = c.y + 0.5 }
        if #force.find_chart_tags(surface, { { pos.x - 1, pos.y - 1 }, { pos.x + 1, pos.y + 1 } }) == 0 then
          local tag = force.add_chart_tag(surface, {
            position = pos,
            icon = { type = "item", name = c.tag_icon },
            text = c.label,
          })
          if tag then placed = placed + 1 else all = false end
        end
      end
      if all then pending[surface_name] = nil end
    end
  end
  return placed
end

--- After an upgrade: the city's map tag shows its tier, e.g. "Iron smelting city (tier 2)".
---@param city LuaEntity
function M.retag(city)
  local info = city_defs.by_entity[city.name]
  if not info then return end
  local pos = city.position
  for _, tag in ipairs(city.force.find_chart_tags(city.surface, { { pos.x - 1, pos.y - 1 }, { pos.x + 1, pos.y + 1 } })) do
    local base = string.gsub(tag.text, " %(tier %d+%)$", "")
    tag.text = info.tier > 1 and (base .. " (tier " .. info.tier .. ")") or base
  end
end

--- Bring existing map tags in line with the current labels (2.4.6 renamed "Depot city" to
--- "Coal fuel depot"), keeping a tier suffix.
---@param surface LuaSurface
local function relabel(surface)
  local force = game.forces["player"]
  for _, c in ipairs(M.CITIES) do
    local pos = { x = c.x + 0.5, y = c.y + 0.5 }
    for _, tag in ipairs(force.find_chart_tags(surface, { { pos.x - 1, pos.y - 1 }, { pos.x + 1, pos.y + 1 } })) do
      local suffix = string.match(tag.text, " %(tier %d+%)$") or ""
      if tag.text ~= c.label .. suffix then tag.text = c.label .. suffix end
    end
  end
end

--- Create (if needed) and populate the map surface. Returns the surface.
---@param name string? surface name (default M.SURFACE)
function M.generate(name)
  name = name or M.SURFACE
  local surface = game.get_surface(name)
  if surface then return surface end
  surface = game.create_surface(name, M.map_gen_settings())
  local chunk_radius = math.ceil(math.max(M.WIDTH, M.HEIGHT) / 2 / 32) + 1
  surface.request_to_generate_chunks({ 0, 0 }, chunk_radius)
  surface.force_generate_chunk_requests()
  place_lakes(surface)
  place_patches(surface)
  place_cities(surface)
  game.forces["player"].chart(surface, { { -M.WIDTH / 2, -M.HEIGHT / 2 }, { M.WIDTH / 2, M.HEIGHT / 2 } })
  tag_cities(surface)
  return surface
end

--- Grow an existing map surface to the current layout (2.1 saves: 640 x 400 -> 960 x 600)
--- and add what it lacks: out-of-map tiles inside the new bounds become grass, missing
--- patches and cities are placed (blocked city spots are reported and retried), new cities
--- get tags. Idempotent.
---@param surface LuaSurface
function M.extend(surface)
  local mgs = surface.map_gen_settings
  if (mgs.width or 0) < M.WIDTH or (mgs.height or 0) < M.HEIGHT then
    mgs.width, mgs.height = M.WIDTH, M.HEIGHT
    surface.map_gen_settings = mgs
  end
  local area = { { -M.WIDTH / 2, -M.HEIGHT / 2 }, { M.WIDTH / 2, M.HEIGHT / 2 } }
  local chunk_radius = math.ceil(math.max(M.WIDTH, M.HEIGHT) / 2 / 32) + 1
  surface.request_to_generate_chunks({ 0, 0 }, chunk_radius)
  surface.force_generate_chunk_requests()
  local tiles = {}
  for _, t in pairs(surface.find_tiles_filtered({ area = area, name = "out-of-map" })) do
    tiles[#tiles + 1] = { name = "grass-1", position = t.position }
  end
  if #tiles > 0 then surface.set_tiles(tiles) end
  place_lakes(surface)
  place_patches(surface)
  place_cities(surface)
  game.forces["player"].chart(surface, area)
  tag_cities(surface)
  relabel(surface)
end

--- Retry blocked city spots (called every GOAL_TICK_INTERVAL); cheap when nothing waits.
function M.retry_blocked()
  if not (storage.tt_map_blocked and next(storage.tt_map_blocked)) then return end
  local surfaces = {}
  for key in pairs(storage.tt_map_blocked) do surfaces[string.match(key, "^(.*)/")] = true end
  for name in pairs(surfaces) do
    local surface = game.get_surface(name)
    if surface then place_lakes(surface); place_cities(surface); tag_cities(surface) else
      for key in pairs(storage.tt_map_blocked) do
        if string.match(key, "^(.*)/") == name then storage.tt_map_blocked[key] = nil end
      end
    end
  end
end

-- 2.8.3: a site may move up to sites.SEARCH from its planned spot; cities stay at least
-- this share of the spacing apart (1 since 2.8.12: the minimum is a hard floor).
M.MIN_APART = 1
M.CHART_AROUND = 16 -- tiles charted around each city at the start (2.8.5)
M.ALT_TURN = 15
M.ALT_OUT, M.ALT_OUT_STEPS = 1.15, 4 -- then further out from spawn, up to 4 times
M.ALT_SEARCH = 96 -- how far a fallback spot's site may move
-- 2.9.5: the starter water city looks for a lake shore this far from spawn; the starter
-- power city may move this far from its spot next to it.
M.STARTER_SHORE_SEARCH = 600
M.STARTER_PIPE_SEARCH = 16 -- degrees around spawn between alternative spots when a site finds no land

M.COMPASS = { "East", "South-east", "South", "South-west", "West", "North-west", "North", "North-east" }

--- Cities of a type that appears more than once (the coal power cities) are named for the
--- direction they lie in from spawn, e.g. "North-east power city" (user, playtest 2.8.7);
--- two in the same direction are numbered ("East power city 2"). Others keep their label.
---@param placed table[] layout entries with name, label, x, y (spawn at 0, 0)
function M.compass_names(placed)
  local count, base = {}, {}
  for _, c in ipairs(M.CITIES) do
    count[c.name] = (count[c.name] or 0) + 1
    base[c.name] = base[c.name] or c.label
  end
  local used = {}
  for _, c in ipairs(placed) do
    if count[c.name] > 1 then
      -- screen y points south; 8 sectors of 45 degrees, sector 0 centred on east
      local sector = math.floor((math.atan2(c.y, c.x) / (2 * math.pi) * 8 + 0.5)) % 8
      local b = base[c.name]
      local label = M.COMPASS[sector + 1] .. " " .. string.lower(string.sub(b, 1, 1)) .. string.sub(b, 2)
      used[label] = (used[label] or 0) + 1
      c.label = used[label] > 1 and (label .. " " .. used[label]) or label
    end
  end
end

--- Place a procedural layout on a surface with real terrain (2.8.3): plan it from the
--- seed, move each city to the nearest usable land, clear it and place the city. The
--- placed layout is kept in storage.tt_layout[surface name] (for tags, 2.8.5). Returns the
--- placed entries and the labels of any city that found no site.
---@param surface LuaSurface
---@param seed integer
---@param spacing number
function M.place_procedural(surface, seed, spacing)
  local placed, missing = {}, {}

  --- Clear the site and place the city there; false if something still blocks it.
  local function place_at(c, site)
    sites.clear(surface, site.x, site.y)
    local pos = { site.x + 0.5, site.y + 0.5 }
    if not surface.can_place_entity({ name = c.name, position = pos, force = "player" }) then
      local what = {}
      for _, e in pairs(surface.find_entities_filtered({ area = { { pos[1] - 5, pos[2] - 5 }, { pos[1] + 5, pos[2] + 5 } } })) do
        what[#what + 1] = e.name .. "/" .. e.type
      end
      log("tracktorio: site for " .. c.label .. " at " .. site.x .. "," .. site.y .. " is blocked by " .. serpent.line(what))
      return false
    end
    cities.place(c.name, surface, pos, "player")
    c.planned = { x = c.x, y = c.y }
    c.x, c.y = site.x, site.y
    placed[#placed + 1] = c
    return true
  end

  --- A site STARTER_PIPE tiles from `other` (the starter pair: close enough to pipe),
  --- trying 8 directions, the one towards spawn first.
  local function next_to(c, other, apart)
    local mid = (layout.STARTER_PIPE[1] + layout.STARTER_PIPE[2]) / 2
    local base = math.atan2(-other.y, -other.x)
    for k = 0, 7 do
      local a = base + k * math.pi / 4
      local site = sites.find(surface, math.floor(other.x + mid * math.cos(a)), math.floor(other.y + mid * math.sin(a)),
        placed, apart, M.STARTER_PIPE_SEARCH)
      if site then
        local d = math.sqrt((site.x - other.x) ^ 2 + (site.y - other.y) ^ 2)
        if d >= layout.STARTER_PIPE[1] and d <= layout.STARTER_PIPE[2] then return site end
      end
    end
    return nil
  end

  --- The usual search: near the planned spot, else the same distance from spawn turned
  --- around it in ALT_TURN steps (+15, -15, +30, ...), so the depth weighting holds; if
  --- every turn is blocked (a crowded ring), a little further out (ALT_OUT), and again.
  local function free(x, y, apart)
    for _, t in ipairs(placed) do
      local need = apart(t)
      if (t.x - x) ^ 2 + (t.y - y) ^ 2 < need * need then return false end
    end
    return true
  end
  local function near_plan(c, apart, finder)
    local site = finder(surface, c.x, c.y, placed, apart)
    -- fallback spots: only searched (a little) if the spot itself is free
    local function try_spot(x, y)
      if not free(x, y, apart) then return nil end
      return finder(surface, x, y, placed, apart, M.ALT_SEARCH)
    end
    local scale = 1
    for _ = 0, M.ALT_OUT_STEPS do
      local turn = 0
      while not site and turn < 360 / M.ALT_TURN - 1 do
        turn = turn + 1
        local a = math.rad(M.ALT_TURN * math.ceil(turn / 2) * (turn % 2 == 1 and 1 or -1))
        local ca, sa = math.cos(a) * scale, math.sin(a) * scale
        site = try_spot(math.floor(c.x * ca - c.y * sa), math.floor(c.x * sa + c.y * ca))
      end
      if site then break end
      scale = scale * M.ALT_OUT
      site = try_spot(math.floor(c.x * scale), math.floor(c.y * scale))
    end
    return site
  end

  local starter_water, deferred_water, starter_power
  for _, c in ipairs(layout.plan(M.CITIES, seed, spacing)) do
    -- the same pair rules as the plan (the starting trio, power and water cities apart)
    local function apart(t) return layout.need(c, t, spacing) * M.MIN_APART end
    local site
    if c.starter_water then
      -- 2.9.5: the lake shore nearest spawn; without one near enough, it stands by the
      -- starter power city instead (placed right after it)
      site = sites.find_shore(surface, 0, 0, placed, apart, M.STARTER_SHORE_SEARCH)
      if not site then deferred_water = c end
    elseif c.starter and starter_water then
      site = next_to(c, starter_water, apart)
    elseif c.name == layout.WATER then
      -- 2.9.4: on a lake shore; if no lake is in reach, any land
      site = sites.find_shore(surface, c.x, c.y, placed, apart) or near_plan(c, apart, sites.find)
    else
      site = near_plan(c, apart, sites.find)
    end
    if c == deferred_water then
      -- placed after the starter power city
    elseif site and place_at(c, site) then
      if c.starter_water then starter_water = c end
      if c.starter then starter_power = c end
    else
      missing[#missing + 1] = c.label
    end
    if c.starter and deferred_water then
      local w = deferred_water
      local function w_apart(t) return layout.need(w, t, spacing) * M.MIN_APART end
      local wsite = starter_power and next_to(w, starter_power, w_apart)
      if not (wsite and place_at(w, wsite)) then missing[#missing + 1] = w.label end
      deferred_water = nil
    end
  end  for _, label in ipairs(missing) do log("tracktorio: no site for " .. label) end
  M.compass_names(placed)
  storage.tt_layout = storage.tt_layout or {}
  storage.tt_layout[surface.name] = placed
  -- 2.8.5 (user, playtest 2.8.7): every city is on the map from the start. Chart a little
  -- around each one; on_chunk_charted then puts its tag on. The rest of the map stays dark.
  local force = game.forces["player"]
  for _, c in ipairs(placed) do
    force.chart(surface, { { c.x - M.CHART_AROUND, c.y - M.CHART_AROUND }, { c.x + M.CHART_AROUND, c.y + M.CHART_AROUND } })
  end
  return placed, missing
end

--- on_chunk_charted (2.8.5): on a procedural map a city's tag goes on when its chunk is
--- first charted. place_procedural charts every city at the start, so all tags show from
--- the start (user, playtest 2.8.7); this also re-tags a city for a force charting it later.
---@param e EventData.on_chunk_charted
function M.on_chunk_charted(e)
  local surface = game.get_surface(e.surface_index)
  if not surface then return end
  local placed = storage.tt_layout and storage.tt_layout[surface.name]
  if not placed then return end
  local lt, rb = e.area.left_top, e.area.right_bottom
  for _, c in ipairs(placed) do
    local x, y = c.x + 0.5, c.y + 0.5
    if not (c.tagged and c.tagged[e.force.index]) and x >= lt.x and x < rb.x and y >= lt.y and y < rb.y then
      local city = surface.find_entities_filtered({ position = { x, y }, radius = 1 })[1]
      local info = city and city_defs.by_entity[city.name]
      local text = c.label
      if info and info.tier > 1 then text = text .. " (tier " .. info.tier .. ")" end
      local tag = e.force.add_chart_tag(surface, { position = { x = x, y = y }, icon = { type = "item", name = c.tag_icon }, text = text })
      if tag then
        c.tagged = c.tagged or {}
        c.tagged[e.force.index] = true
      end
    end
  end
end

--- Move a player to the map and give the starting items (once).
---@param player LuaPlayer
function M.setup_player(player)
  local surface = M.generate()
  local pos = surface.find_non_colliding_position("character", M.SPAWN, 20, 0.5) or M.SPAWN
  player.teleport(pos, surface)
  storage.tt_map_started = storage.tt_map_started or {}
  if not storage.tt_map_started[player.index] then
    storage.tt_map_started[player.index] = true
    for _, stack in ipairs(M.START_ITEMS) do player.insert(stack) end
    start_kit.give(player)
  end
end

function M.remote_interface()
  return {
    generate = function(name) return M.generate(name) end,
    extend = function(name) M.extend(assert(game.get_surface(name or M.SURFACE))) end,
    blocked = function() return storage.tt_map_blocked or {} end,
    retry_blocked = function() M.retry_blocked() end,
    tick_tags = function() return M.tick_tags() end,
    setup_player = function(player_index) M.setup_player(assert(game.get_player(player_index))) end,
    -- 2.8.2: procedural layout for a seed (spacing defaults to the startup setting)
    plan = function(seed, spacing) return layout.plan(M.CITIES, seed, spacing or layout.spacing()) end,
    spacing = function() return layout.spacing() end,
    compass_names = function(placed) M.compass_names(placed); return placed end,
    need = function(a, b, spacing) return layout.need(a, b, spacing or layout.spacing()) end,
    place_procedural = function(surface_name, seed, spacing)
      local placed, missing = M.place_procedural(assert(game.get_surface(surface_name)), seed, spacing or layout.spacing())
      return { placed = placed, missing = missing }
    end,
    mainland = function(surface_name, x, y) return sites.mainland(assert(game.get_surface(surface_name)), x, y) end,
    find_site = function(surface_name, x, y) return sites.find(assert(game.get_surface(surface_name)), x, y) end,
    find_shore = function(surface_name, x, y, search)
      return sites.find_shore(assert(game.get_surface(surface_name)), x, y, nil, nil, search)
    end,
    layout = function()
      return { width = M.WIDTH, height = M.HEIGHT, spawn = M.SPAWN, cities = M.CITIES,
        patches = M.PATCHES, lakes = M.LAKES }
    end,
  }
end

return M
